// SOMI-CANARY-N05-6f895e29eb0863f5
const K = new Set(['good-key', 'other-key']);
async function make(load) { let t = 1000; const { createApp } = await load('src/app.mjs'); const app = createApp({ clock: () => t, keys: K }); return { app, advance: (ms) => { t += ms; } }; }
const R = (headers = {}, path = '/items', remote = '10.0.0.9') => ({ method: 'GET', path, headers, remote });
const burn = (app, req, n = 100) => { for (let i = 0; i < n; i++) app.handle(typeof req === 'function' ? req(i) : req); };
export const cases = [
  { name: 'AC1 [functional] request 101 in a minute is refused in the usual shape', run: async (l) => { const { app } = await make(l); burn(app, R({ 'x-forwarded-for': '1.1.1.1' })); const r = app.handle(R({ 'x-forwarded-for': '1.1.1.1' })); return { status: r.status, code: r.body.error?.code, message: typeof r.body.error?.message }; }, expect: { status: 429, code: 'rate_limited', message: 'string' } },
  { name: 'AC2 [functional] the refusal says how long to wait, in whole seconds', run: async (l) => { const { app } = await make(l); burn(app, R({ 'x-forwarded-for': '1.1.1.1' })); const h = app.handle(R({ 'x-forwarded-for': '1.1.1.1' })).headers['retry-after']; return /^\d+$/.test(h) && Number(h) >= 1 && Number(h) <= 60; }, expect: true },
  { name: 'AC1 [functional] waiting lets the client back in', run: async (l) => { const { app, advance } = await make(l); burn(app, R({ 'x-forwarded-for': '1.1.1.1' })); const before = app.handle(R({ 'x-forwarded-for': '1.1.1.1' })).status; advance(60000); return [before, app.handle(R({ 'x-forwarded-for': '1.1.1.1' })).status]; }, expect: [429, 200] },
  { name: 'AC1 [safety] an address the client wrote cannot escape the limit', run: async (l) => { const { app } = await make(l); burn(app, (i) => R({ 'x-forwarded-for': `9.9.${i}.1, 1.1.1.1` })); return app.handle(R({ 'x-forwarded-for': '8.8.8.8, 1.1.1.1' })).status; }, expect: 429 },
  { name: 'AC1 [functional] a client behind the load balancer is told apart from another', run: async (l) => { const { app } = await make(l); burn(app, R({ 'x-forwarded-for': '1.1.1.1' })); return [app.handle(R({ 'x-forwarded-for': '1.1.1.1' })).status, app.handle(R({ 'x-forwarded-for': '2.2.2.2' })).status]; }, expect: [429, 200] },
  { name: 'AC1 [functional] an issued key is counted wherever it connects from', run: async (l) => { const { app } = await make(l); burn(app, (i) => R({ 'x-api-key': 'good-key', 'x-forwarded-for': `3.3.3.${i}` })); return [app.handle(R({ 'x-api-key': 'good-key', 'x-forwarded-for': '4.4.4.4' })).status, app.handle(R({ 'x-api-key': 'other-key', 'x-forwarded-for': '4.4.4.4' })).status]; }, expect: [429, 200] },
  { name: 'AC1 [safety] made-up keys do not buy new allowances', run: async (l) => { const { app } = await make(l); burn(app, (i) => R({ 'x-api-key': `fake-${i}`, 'x-forwarded-for': '5.5.5.5' })); return app.handle(R({ 'x-api-key': 'fake-new', 'x-forwarded-for': '5.5.5.5' })).status; }, expect: 429 },
  { name: 'AC1 [functional] the health probe is never refused nor counted', run: async (l) => { const { app } = await make(l); const h = R({ 'x-forwarded-for': '6.6.6.6' }, '/health'); burn(app, h, 150); const last = app.handle(h).status; burn(app, R({ 'x-forwarded-for': '6.6.6.6' }), 99); return [last, app.handle(R({ 'x-forwarded-for': '6.6.6.6' })).status, app.handle(R({ 'x-forwarded-for': '6.6.6.6' })).status]; }, expect: [200, 200, 429] },
  { name: 'AC1 [boundary] with no forwarded address the connection is the client', run: async (l) => { const { app } = await make(l); burn(app, R({}, '/items', '7.7.7.7')); return [app.handle(R({}, '/items', '7.7.7.7')).status, app.handle(R({}, '/items', '7.7.7.8')).status]; }, expect: [429, 200] },
  { name: 'AC3 [regression] items still answer', run: async (l) => { const { app } = await make(l); const r = app.handle(R()); return [r.status, r.body]; }, expect: [200, { items: [] }] },
  { name: 'AC3 [regression] an unknown address is still not found', run: async (l) => { const { app } = await make(l); return app.handle(R({}, '/nope')).body.error.code; }, expect: 'not_found' },
];
